"""Generates one Creator Tools (Lua) build script per instrument.

Running the script in Kontakt Creator Tools fills an empty instrument with all
groups, zones (root, key and velocity ranges), loop points and the KSP
performance script. Then you push it to Kontakt and save the .nki.
"""
from .library import LIB_NAME

HEADER = """-- ==========================================================================
-- {lib} :: Build "{name}"
-- ==========================================================================
-- Generated by tools/nml/lua_gen.py.
--
-- HOW TO USE (takes about a minute):
--   1. In Kontakt 8, double-click the empty rack area to create a NEW, EMPTY
--      instrument.
--   2. Open Creator Tools (installed with Kontakt). In the Instrument Editor
--      (F2), pick that instrument from the drop-down at the top.
--   3. Open the Lua Script panel (Shift+F3), load this file and press Run
--      (Ctrl/Cmd+R).
--   4. Press Push (Ctrl/Cmd+Alt+Up) so the changes go to Kontakt.
--   5. In Kontakt: File > Save as... and save it as
--        {lib}/Instruments/{cat}/{name}.nki
--      ("Patch only", and keep "absolute sample paths" OFF).
--
-- The script only reads files inside the "{lib}" folder, relative to the
-- location of this script, so you can put the library on any drive.
-- ==========================================================================
"""

BODY = r'''
if not instrument then
  print("No instrument connected. Create an empty instrument in Kontakt, select it in the")
  print("Creator Tools instrument drop-down and run this script again.")
  return
end

local function stripSep(p)
  while #p > 1 and (p:sub(-1) == "/" or p:sub(-1) == "\\") do p = p:sub(1, -2) end
  return p
end

local LIB = filesystem.parentPath(stripSep(scriptPath))
local missing = 0
local zoneCount = 0

local function samplePath(rel)
  return filesystem.preferred(LIB .. "/" .. rel)
end

-- start from a clean instrument
local initialGroups = 0
pcall(function() instrument.groups:reset() end)
initialGroups = #instrument.groups

local function newGroup(name)
  instrument.groups:add(Group())
  local g = instrument.groups[#instrument.groups - 1]
  g.name = name
  pcall(function() g.playbackMode = PlaybackMode.Sampler end)
  return g
end

local function addZone(g, rel, root, lo, hi, vlo, vhi, loopStart, loopLen)
  local path = samplePath(rel)
  if not filesystem.exists(path) then
    print("MISSING SAMPLE: " .. path)
    missing = missing + 1
    return
  end
  g.zones:add(Zone())
  local z = g.zones[#g.zones - 1]
  z.file = path
  z.rootKey = root
  z.keyRange.low = lo
  z.keyRange.high = hi
  z.velocityRange.low = vlo
  z.velocityRange.high = vhi
  if loopStart then
    pcall(function()
      if #z.loops == 0 then z.loops:resize(1) end
      z.loops[0].mode = 1        -- 1 = loop until end (keeps looping in the release)
      z.loops[0].start = loopStart
      z.loops[0].length = loopLen
      z.loops[0].xfade = 0        -- the crossfade is already baked into the sample
    end)
  end
  zoneCount = zoneCount + 1
end
'''

FOOTER = r'''
-- remove the empty default group(s) the reset left behind
for i = initialGroups - 1, 0, -1 do
  local g = instrument.groups[i]
  if g and #g.zones == 0 then instrument.groups:remove(i) end
end

pcall(function() instrument.name = INSTRUMENT_NAME end)

-- attach the performance script (slot 1)
local scriptOk = pcall(function()
  local s = instrument.scripts[0]
  s.name = SCRIPT_NAME
  s.sourceCode = KSP_SOURCE
  s.bypass = false
end)
if not scriptOk then
  scriptOk = pcall(function()
    instrument.script.name = SCRIPT_NAME
    instrument.script.sourceCode = KSP_SOURCE
    instrument.script.bypass = false
  end)
end

print("------------------------------------------------------------")
print(INSTRUMENT_NAME .. ": " .. zoneCount .. " zones in " .. #instrument.groups .. " groups.")
if missing > 0 then
  print("WARNING: " .. missing .. " samples were not found. Is this script still inside")
  print("'" .. LIB_NAME .. "/Creator Tools'?")
end
if scriptOk then
  print("Performance script attached. If Kontakt shows it un-applied, open the")
  print("Script Editor and press Apply.")
else
  print("Could not attach the script automatically: open the Script Editor in Kontakt,")
  print("paste Resources/scripts/" .. SCRIPT_FILE .. " into slot 1 and press Apply.")
end
print("Now press PUSH, then save the instrument in Kontakt.")
'''


def _lua_str(s):
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


def generate(inst, ksp_text, script_file):
    assert "]==]" not in ksp_text
    out = [HEADER.format(lib=LIB_NAME, name=inst.name, cat=inst.category)]
    out.append(f"local INSTRUMENT_NAME = {_lua_str(inst.name)}")
    out.append(f"local LIB_NAME = {_lua_str(LIB_NAME)}")
    out.append(f"local SCRIPT_NAME = {_lua_str('NML ' + inst.name)}")
    out.append(f"local SCRIPT_FILE = {_lua_str(script_file)}")
    out.append(BODY)
    for g in inst.groups:
        out.append(f"do  -- group {g}")
        out.append(f"  local g = newGroup({_lua_str(g)})")
        for z in inst.zones:
            if z.group != g:
                continue
            loop = f", {z.loop[0]}, {z.loop[1] - z.loop[0]}" if z.loop else ""
            out.append(f"  addZone(g, {_lua_str(z.file)}, {z.root}, {z.lo}, {z.hi}, {z.vlo}, {z.vhi}{loop})")
        out.append("end")
    out.append("")
    out.append("local KSP_SOURCE = [==[")
    out.append(ksp_text.rstrip("\n"))
    out.append("]==]")
    out.append(FOOTER)
    return "\n".join(out)
